:root{color-scheme:light;--lp-max-width:550px}
*{box-sizing:border-box}
html{scroll-behavior:smooth;background:#e9e9ee}
body{margin:0;font-family:"Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;color:#111;background:#e9e9ee}
.lp-page{width:min(100%,var(--lp-max-width));margin:0 auto;background:#fff;box-shadow:0 18px 60px rgba(15,23,42,.16);overflow:hidden}
.lp-section{position:relative;width:100%;aspect-ratio:var(--section-ratio);overflow:hidden;container-type:inline-size;isolation:isolate}
.lp-visual-layer{position:absolute;inset:0;width:100%;height:100%;z-index:1;overflow:hidden;pointer-events:none}
.lp-asset,.lp-vector{pointer-events:none}
.lp-text{position:absolute;margin:0;white-space:nowrap;overflow:visible;font-kerning:normal;text-rendering:geometricPrecision;user-select:text;-webkit-user-select:text;cursor:text}
.lp-text-run{white-space:inherit;user-select:text;-webkit-user-select:text}
.lp-vertical-glyph{position:absolute;left:0;display:block;width:1em;height:1em;line-height:1;letter-spacing:0;word-spacing:0;white-space:nowrap;writing-mode:vertical-rl;text-orientation:mixed}
.lp-text--pdf-svg{position:absolute;inset:0;width:100%;height:100%;margin:0;overflow:visible;pointer-events:none;user-select:text;-webkit-user-select:text}
.lp-native-text-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;user-select:none;-webkit-user-select:none}
.lp-native-text-svg text,.lp-native-text-svg tspan{pointer-events:none;user-select:none;-webkit-user-select:none}
.lp-selection-text{position:absolute;display:block;margin:0;overflow:visible;white-space:pre-wrap;color:transparent;-webkit-text-fill-color:transparent;-webkit-text-stroke:0 transparent;text-shadow:none;pointer-events:auto;user-select:text;-webkit-user-select:text;cursor:text;z-index:1}
.lp-text--selection-only,.lp-text--selection-only .lp-text-run,.lp-text--selection-only .lp-vertical-glyph{color:transparent!important;-webkit-text-fill-color:transparent!important;-webkit-text-stroke:0 transparent!important;text-shadow:none!important;opacity:1!important;pointer-events:auto;user-select:text;-webkit-user-select:text;cursor:text}
.lp-selection-text::selection,.lp-text--selection-only::selection,.lp-text--selection-only *::selection{background:rgba(37,99,235,.3);color:transparent;-webkit-text-fill-color:transparent}
.lp-text[data-source="ocr"]{white-space:pre-wrap;overflow-wrap:anywhere}
.lp-text--cta{display:block;text-decoration:none}
.lp-text--price{font-variant-numeric:tabular-nums}
.lp-smart-section{position:relative;width:100%;container-type:inline-size;background-color:var(--lp-section-color,#fff);background-image:var(--lp-section-image,none)}
.lp-smart-section__inner{width:min(100%,70rem);margin:0 auto;padding:clamp(2rem,7cqw,5rem);display:grid;gap:clamp(1.5rem,5cqw,3.5rem);align-items:center}
.lp-smart-section__inner--copy-only{max-width:54rem}
.lp-smart-copy{display:flex;min-width:0;flex-direction:column;align-items:stretch;gap:clamp(.75rem,2.6cqw,1.5rem)}
.lp-smart-copy__text{margin:0;color:var(--lp-copy-color,#111);font-family:var(--lp-copy-font,inherit);font-size:var(--lp-copy-size,1rem);font-style:var(--lp-copy-style,normal);font-weight:var(--lp-copy-weight,400);line-height:var(--lp-copy-leading,1.7);text-align:var(--lp-copy-align,left);writing-mode:var(--lp-copy-writing,horizontal-tb);direction:var(--lp-copy-direction,ltr);overflow-wrap:anywhere;user-select:text;-webkit-user-select:text}
.lp-smart-copy__text--heading{letter-spacing:0;text-wrap:balance}
.lp-smart-copy__text--body,.lp-smart-copy__text--offer-condition{max-width:44rem}
.lp-smart-copy__text--price{display:block;font-variant-numeric:tabular-nums}
.lp-smart-copy__text--legal{color:color-mix(in srgb,var(--lp-copy-color,#111) 72%,transparent)}
.lp-smart-copy__text--label{align-self:flex-start}
.lp-smart-copy__text--cta{display:inline-flex;min-height:48px;align-self:flex-start;align-items:center;justify-content:center;padding:.8em 1.5em;border:1px solid #171717;border-radius:6px;color:#fff;background:#171717;text-decoration:none}
.lp-smart-run{color:var(--lp-run-color,currentColor)}
.lp-smart-media{display:grid;gap:1rem;align-items:center}
.lp-smart-media__item{margin:0;min-width:0}
.lp-smart-media__item img{display:block;width:100%;height:auto;max-height:34rem;object-fit:contain}
.lp-link-area{position:absolute;z-index:100001;display:block;overflow:visible;border-radius:var(--lp-link-radius,0);color:inherit;text-decoration:none;cursor:url("data:image/png;base64,") 16 21,pointer;isolation:isolate;touch-action:manipulation}
.lp-link-area--animation-only{pointer-events:none;cursor:default}
.lp-link-area::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;opacity:0;transform-origin:center}
.lp-link-area:focus-visible{outline:max(2px,.35cqw) solid #2563eb;outline-offset:max(2px,.25cqw)}
.lp-link-area--pulse::after{opacity:.42;background:rgba(255,255,255,.16);box-shadow:inset 0 0 0 max(2px,.22cqw) rgba(255,255,255,.82),0 0 max(5px,.9cqw) rgba(240,40,116,.5);animation:lp-link-pulse 1.8s ease-in-out infinite}
.lp-link-area--shine{overflow:hidden}
.lp-link-area--shine::after{inset:0 auto 0 -70%;width:45%;opacity:1;background:linear-gradient(110deg,transparent,rgba(255,255,255,.72),transparent);transform:skewX(-18deg);animation:lp-link-shine 2.4s ease-in-out infinite}
.lp-link-area--glow::after{opacity:1;box-shadow:inset 0 0 max(5px,1.8cqw) rgba(255,255,255,.78),0 0 max(7px,1.5cqw) rgba(236,72,153,.58);animation:lp-link-glow 1.7s ease-in-out infinite}
.lp-link-area--bounce,.lp-link-area--heartbeat,.lp-link-area--float{transform-origin:center;will-change:transform}
.lp-link-area--bounce{animation:lp-link-bounce 2s cubic-bezier(.28,.84,.42,1) infinite}
.lp-link-area--heartbeat{animation:lp-link-heartbeat 1.65s ease-in-out infinite}
.lp-link-area--float{animation:lp-link-float 3s ease-in-out infinite}
.lp-link-area--bounce::after,.lp-link-area--heartbeat::after,.lp-link-area--float::after{opacity:.72;background:rgba(255,255,255,.12);box-shadow:inset 0 0 0 max(2px,.22cqw) rgba(255,255,255,.76),0 0 max(7px,1.2cqw) rgba(240,40,116,.58)}
.lp-link-area--object-target{animation:none!important;transform:none!important}
.lp-link-area--object-target::after{animation:none!important;opacity:0!important;background:none!important;box-shadow:none!important;transform:none!important}
.lp-object-effect{will-change:translate,scale,rotate,filter}
.lp-object-effect--pulse{animation:lp-object-pulse 1.8s ease-in-out infinite}
.lp-object-effect--glow{animation:lp-object-glow 1.7s ease-in-out infinite}
.lp-object-effect--bounce{animation:lp-object-bounce 2s cubic-bezier(.28,.84,.42,1) infinite}
.lp-object-effect--heartbeat{animation:lp-object-heartbeat 1.65s ease-in-out infinite}
.lp-object-effect--float{animation:lp-object-float 3s ease-in-out infinite}.lp-object-effect--float-straight{animation:lp-object-float-straight 3s ease-in-out infinite}
.lp-visually-hidden{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
@keyframes lp-link-pulse{0%,100%{opacity:.38;transform:scale(.965);box-shadow:inset 0 0 0 max(2px,.22cqw) rgba(255,255,255,.72),0 0 max(4px,.7cqw) rgba(240,40,116,.4)}50%{opacity:1;transform:scale(1.025);box-shadow:inset 0 0 0 max(2px,.3cqw) rgba(255,255,255,.96),0 0 max(10px,1.8cqw) rgba(240,40,116,.82)}}
@keyframes lp-link-shine{0%,28%{left:-70%}72%,100%{left:135%}}
@keyframes lp-link-glow{0%,100%{box-shadow:inset 0 0 max(4px,1.2cqw) rgba(255,255,255,.58),0 0 max(6px,1.1cqw) rgba(236,72,153,.45)}50%{box-shadow:inset 0 0 max(8px,2.4cqw) rgba(255,255,255,.94),0 0 max(16px,3cqw) rgba(236,72,153,.95)}}
@keyframes lp-link-bounce{0%,20%,53%,80%,100%{transform:translateY(0)}40%,43%{transform:translateY(-18%)}70%{transform:translateY(-8%)}90%{transform:translateY(-3%)}}
@keyframes lp-link-heartbeat{0%,38%,100%{transform:scale(1)}12%{transform:scale(1.07)}24%{transform:scale(.97)}31%{transform:scale(1.13)}}
@keyframes lp-link-float{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-5%) rotate(.18deg)}}
@keyframes lp-object-pulse{0%,100%{scale:.97;filter:brightness(1)}50%{scale:1.045;filter:brightness(1.12)}}
@keyframes lp-object-glow{0%,100%{filter:drop-shadow(0 0 max(3px,.65cqw) rgba(236,72,153,.42)) brightness(1)}50%{filter:drop-shadow(0 0 max(12px,2.2cqw) rgba(236,72,153,.95)) brightness(1.12)}}
@keyframes lp-object-bounce{0%,20%,53%,80%,100%{translate:0 0}40%,43%{translate:0 calc(-1 * var(--lp-effect-shift-y))}70%{translate:0 calc(-.45 * var(--lp-effect-shift-y))}90%{translate:0 calc(-.18 * var(--lp-effect-shift-y))}}
@keyframes lp-object-heartbeat{0%,38%,100%{scale:1}12%{scale:1.07}24%{scale:.97}31%{scale:1.13}}
@keyframes lp-object-float{0%,100%{translate:0 0;rotate:0deg}50%{translate:0 calc(-.28 * var(--lp-effect-shift-y));rotate:.18deg}}@keyframes lp-object-float-straight{0%,100%{translate:0 0}50%{translate:0 -5px}}

@media(max-width:560px){.lp-page{box-shadow:none}}
@media(min-width:700px){.lp-smart-section__inner--with-media{grid-template-columns:minmax(0,1.08fr) minmax(14rem,.92fr)}.lp-smart-media{grid-column:2;grid-row:1}.lp-smart-copy{grid-column:1;grid-row:1}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.lp-link-area,.lp-link-area::after,.lp-object-effect{animation:none!important;transform:none!important;translate:none!important;scale:none!important;rotate:none!important;filter:none!important}}
  